package streampolicy

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"slices"
	"strings"
	"unicode/utf8"
)

type candidateAdapter struct {
	Candidate
	client *http.Client
}

// candidateViolation carries a fixed diagnostic generated by the wire adapter.
type candidateViolation string

func (e candidateViolation) Error() string { return string(e) }
func (e candidateViolation) Unwrap() error { return ErrViolation }

func newCandidateAdapter(candidate Candidate) *candidateAdapter {
	transport := &http.Transport{
		DisableKeepAlives:      true,
		DisableCompression:     true,
		MaxResponseHeaderBytes: MaxEvidenceBytes,
	}
	client := &http.Client{
		Transport: transport,
		CheckRedirect: func(*http.Request, []*http.Request) error {
			return http.ErrUseLastResponse
		},
	}
	return &candidateAdapter{Candidate: candidate, client: client}
}

func readEvidence(reader io.ReadCloser) ([]byte, error) {
	if reader == nil {
		return nil, ErrIncomplete
	}
	raw, readErr := io.ReadAll(io.LimitReader(reader, MaxEvidenceBytes+1))
	if err := errors.Join(readErr, reader.Close()); err != nil {
		return nil, err
	}
	if len(raw) > MaxEvidenceBytes {
		return nil, ErrIncomplete
	}
	return raw, nil
}

func (a *candidateAdapter) exchange(ctx context.Context, probe CandidateRequest, body string) (Response, error) {
	if err := ctx.Err(); err != nil {
		return Response{}, err
	}
	request, err := a.Request(ctx, probe)
	if err != nil || request == nil {
		if request != nil && request.Body != nil {
			err = errors.Join(err, request.Body.Close())
		}
		return Response{}, errors.Join(ErrIncomplete, err)
	}
	// The binding owns routing and credentials. The adapter owns request
	// framing and cancellation, including sending the original NDJSON bytes.
	request = request.Clone(ctx)
	if request.Body != nil && request.Body != http.NoBody {
		return Response{}, errors.Join(ErrIncomplete, request.Body.Close())
	}
	if probe.Operation == CandidateIngest {
		request.Body = io.NopCloser(strings.NewReader(body))
		request.GetBody = nil
		request.ContentLength = int64(len(body))
		if request.Header == nil {
			request.Header = make(http.Header)
		}
		request.Header.Set("Content-Type", "application/x-ndjson")
	}
	reply, err := a.client.Do(request)
	if err != nil {
		return Response{}, err
	}
	raw, err := readEvidence(reply.Body)
	if err != nil {
		return Response{}, err
	}
	if reply.StatusCode == http.StatusNotImplemented {
		return Response{}, ErrIncomplete
	}
	// Observe trailers after EOF. In particular a cursor hidden in a trailer
	// is still a disclosure on denial and invalid on a successful page.
	headers := applicationHeaders(reply.Header)
	trailers := applicationHeaders(reply.Trailer)
	if _, ok := trailers["Bog-Next-Cursor"]; ok {
		return Response{}, candidateViolation("query cursor appeared in an HTTP trailer")
	}
	for key, values := range trailers {
		headers[key] = append(headers[key], values...)
	}
	response := Response{Complete: true, Status: reply.StatusCode, Body: raw, Headers: headers}
	if err := inspectSurfaces(response, func([]byte) error { return nil }); err != nil {
		return Response{}, err
	}
	return response, nil
}

func applicationHeaders(headers http.Header) http.Header {
	app := make(http.Header, len(headers))
	for name, values := range headers {
		key := http.CanonicalHeaderKey(name)
		switch key {
		case "Connection", "Date", "Keep-Alive", "Transfer-Encoding", "Trailer":
			continue
		}
		app[key] = slices.Clone(values)
	}
	return app
}

func (a *candidateAdapter) Ingest(ctx context.Context, request IngestRequest) (Response, error) {
	return a.exchange(ctx, CandidateRequest{Operation: CandidateIngest, Target: request.Target}, request.Body)
}

func (a *candidateAdapter) Query(ctx context.Context, request QueryRequest) (Page, error) {
	response, err := a.exchange(ctx, CandidateRequest{Operation: CandidateQuery, Target: request.Target, Query: request}, "")
	if err != nil {
		return Page{}, err
	}
	page := Page{Response: response}
	if values := page.Headers["Bog-Next-Cursor"]; len(values) == 1 {
		page.NextCursor = values[0]
	}
	rows, err := observeQueryRows(response.Body, response.Status == http.StatusOK)
	if err != nil {
		return Page{}, err
	}
	page.Rows = rows
	return page, nil
}

func observeQueryRows(body []byte, success bool) ([]Row, error) {
	var rows []Row
	for len(body) > 0 {
		line, rest, terminated := bytes.Cut(body, []byte("\n"))
		body = rest
		var fields map[string]json.RawMessage
		var ts, text *string
		valid := utf8.Valid(line) && json.Unmarshal(line, &fields) == nil &&
			json.Unmarshal(fields["ts"], &ts) == nil && ts != nil &&
			json.Unmarshal(fields["line"], &text) == nil && text != nil
		if success && (!terminated || !valid || len(fields) != 2) {
			return nil, candidateViolation("successful query returned malformed NDJSON")
		}
		// Application errors need not be NDJSON. Still record any row-shaped
		// data, even if it has other fields or omits a final line delimiter.
		if valid {
			rows = append(rows, Row{Timestamp: *ts, Line: *text})
		}
	}
	return rows, nil
}

func (a *candidateAdapter) CreateExport(ctx context.Context, target Target) (ExportStart, error) {
	response, err := a.exchange(ctx, CandidateRequest{Operation: CandidateCreateExport, Target: target}, "")
	if err != nil {
		return ExportStart{}, err
	}
	// The binding can inspect response fields without owning the raw evidence.
	id, err := a.ExportID(Response{
		Complete: response.Complete, Status: response.Status,
		Body: slices.Clone(response.Body), Headers: http.Header(response.Headers).Clone(),
	})
	return ExportStart{Response: response, ArtifactID: id}, err
}

func (a *candidateAdapter) FetchExport(ctx context.Context, target Target, id string) (Artifact, error) {
	response, err := a.exchange(ctx, CandidateRequest{Operation: CandidateFetchExport, Target: target, ArtifactID: id}, "")
	if err != nil {
		return Artifact{}, err
	}
	artifact := Artifact{Response: response}
	if len(response.Body) == 0 {
		return artifact, nil
	}
	manifest, records, verifyErr := a.VerifyArtifact(ctx, slices.Clone(response.Body))
	if response.Status/100 != 2 && verifyErr != nil {
		// Ordinary denial bodies are not artifacts. The raw response is still
		// available for the denial comparison and disclosure checks.
		return artifact, nil
	}
	artifact.Bytes = response.Body
	artifact.Manifest = manifest
	artifact.Records = records
	artifact.Verified = verifyErr == nil
	return artifact, nil
}

func (a *candidateAdapter) committed(ctx context.Context) (Committed, error) {
	reader, err := a.Evidence.OpenCommitted(ctx)
	if err != nil {
		if reader != nil {
			err = errors.Join(err, reader.Close())
		}
		return Committed{}, err
	}
	raw, err := readEvidence(reader)
	if err != nil {
		return Committed{}, err
	}
	if len(raw) == 0 {
		return Committed{}, ErrIncomplete
	}
	records, err := a.Evidence.DecodeCommitted(ctx, slices.Clone(raw))
	return Committed{Complete: err == nil && records != nil, Bytes: raw, Records: records}, err
}

func (a *candidateAdapter) RestartAndReplay(ctx context.Context) (Committed, error) {
	evidence, err := a.committed(ctx)
	if err != nil || !evidence.Complete {
		return Committed{}, errors.Join(ErrIncomplete, err)
	}
	if err := a.Evidence.Restart(ctx); err != nil {
		return Committed{}, err
	}
	return evidence, nil
}

func (a *candidateAdapter) checkCommitted(ctx context.Context, want []Record, forbidden []string) error {
	evidence, err := a.committed(ctx)
	if err := observation(ctx, err); err != nil {
		return err
	}
	if !evidence.Complete {
		return ErrIncomplete
	}
	return inspectRecords(evidence.Bytes, evidence.Records, want, forbidden)
}
